import csv, json
from pathlib import Path
p=Path('product_catalog/C-tvs-video-home-entertainment.csv')
with p.open(encoding='utf-8-sig',newline='') as f:
 r=csv.DictReader(f); cols=r.fieldnames; rows=list(r)
keys={(x['brand'].lower(),x['model'].lower()) for x in rows}
def add(brand,model,name,sub,typ,desc,spec,url,source,year,date='',price='',currency='',ptype='',market='',notes=''):
 if (brand.lower(),model.lower()) in keys:return
 keys.add((brand.lower(),model.lower()))
 rows.append(dict(category_code='C',department='TVs, Video & Home Entertainment',subcategory=sub,product_type=typ,product_name=name,manufacturer=brand,brand=brand,model=model,manufacturer_part_number=model,gtin='',description=desc,specifications_json=json.dumps(spec,separators=(',',':')),image_url='',product_url=url,release_date=date,release_date_precision='day' if len(date)==10 else ('month' if len(date)==7 else 'year'),release_year=year,official_price=price,price_currency=currency,price_type=ptype,price_market=market,price_source_url=source if price else '',product_source_url=source,source_attribution='Official manufacturer page/announcement',collected_on='2026-10-13',verification_status='official_manufacturer_source_verified',notes=notes+' Official image URL not captured; confirm from product gallery before import.'))
add('Panasonic','TV-65Z95B','Panasonic VIERA 65-inch Z95B OLED TV','Televisions','OLED 4K TV','2025 65-inch 4K OLED flagship with Primary RGB Tandem panel and Fire TV.',{'size':'65 inch','panel':'OLED Primary RGB Tandem','resolution':'3840x2160','audio':'170 W max','HDMI':4,'USB':3,'smart_platform':'Fire TV'},'https://panasonic.jp/viera/products/TV-65Z95B/spec.html','https://news.panasonic.com/jp/press/jn250512-2','2025','2025-06',notes='Announced May 2025; Japan release late June; price open/not stated.')
add('Panasonic','TV-65Z90B','Panasonic VIERA 65-inch Z90B OLED TV','Televisions','OLED 4K TV','2025 65-inch 4K OLED smart television with Fire TV.',{'size':'65 inch','panel':'OLED','resolution':'4K','smart_platform':'Fire TV'},'https://panasonic.jp/viera/products/TV-65Z90B.html','https://news.panasonic.com/jp/press/jn250512-2','2025','2025-06',notes='Announced May 2025; Japan release late June; price not stated.')
add('Panasonic','W95B series 55-85 inch','Panasonic W95B Mini LED TV Series','Televisions','Mini-LED 4K TV','2025 Mini LED family with Fire TV and HDR gaming.',{'sizes_inch':[55,65,75,85],'display':'Mini LED','processor':'HCX Pro AI Processor MK II','refresh_rate':'Up to 144 Hz','gaming':'HDMI 2.1; AMD FreeSync Premium; VRR','audio':'20 W subwoofer'},'https://na.panasonic.com/news/panasonic-introduces-2025-flagship-w95b-series-mini-led-tv-with-improved-picture-performance-and-fire-tv-built-in-enhancements','https://na.panasonic.com/news/panasonic-introduces-2025-flagship-w95b-series-mini-led-tv-with-improved-picture-performance-and-fire-tv-built-in-enhancements','2025','2025-01-07',notes='Family-level record; exact size-specific model codes/prices not in captured announcement.')
add('Sony','K-65XR50','Sony BRAVIA 5 65-inch Mini LED 4K Google TV','Televisions','Mini-LED 4K Google TV','65-inch Mini LED LCD television.',{'size':'65 inch','resolution':'3840x2160','panel':'LCD Mini LED local dimming','refresh_rate':'120 Hz','HDR':['HDR10','HLG','Dolby Vision'],'smart_platform':'Google TV','HDMI':'4; 4K120/eARC/VRR/ALLM','wifi':'Wi-Fi 6'},'https://electronics.sony.com/tv-video/televisions/all-tvs/p/k65xr50','https://www.sony.com/electronics/support/televisions-projectors-lcd-tvs-android-/k-65xr50/specifications','2025',price='1499.99',currency='USD',ptype='current_listed',market='United States',notes='Sony confirms 2025 model year; current price $1,499.99.')
add('Sony','K-65XR80M2','Sony BRAVIA 8 II 65-inch QD-OLED 4K Google TV','Televisions','QD-OLED 4K Google TV','65-inch QD-OLED television with XR processor.',{'size':'65 inch','resolution':'3840x2160','panel':'QD-OLED','refresh_rate':'120 Hz','HDR':['HDR10','HLG','Dolby Vision'],'smart_platform':'Google TV','gaming':'4K120; VRR; ALLM'},'https://electronics.sony.com/tv-video/televisions/all-tvs/p/k65xr80m2','https://www.sony.com/electronics/support/televisions-projectors-oled-tvs-android-/k-65xr80m2/specifications','2025',price='2499.99',currency='USD',ptype='current_listed',market='United States',notes='Sony confirms 2025 model; price captured $2,499.99 sale, MSRP $3,299.99.')
add('Hisense','100U8QG','Hisense 100-inch U8 MiniLED ULED 4K Google TV','Televisions','MiniLED ULED 4K TV','100-inch 4K MiniLED Google TV from Hisense 2025 ULED line.',{'size':'100 inch','resolution':'4K','display':'MiniLED Pro; QLED','peak_brightness':'Up to 5000 nits','refresh_rate_native':'165 Hz','audio':'Up to 82 W, 4.1.2 channel','smart_platform':'Google TV'},'https://www.hisense-usa.com/product-page/televisions-100-class-u8-series-miniled-uled-4k-google-tv-100u8qg','https://files.hisense-usa.com/download/f2767e4653594894','2025',notes='Official 2025 ULED release and product listing; price not captured.')
